#!/usr/bin/env pwsh
# Generated by Claude Opus 4.8 (claude.ai/code) · 2026-11-11

<#
.SYNOPSIS
  Backup sequencer — plan, run, and review service backups.
.DESCRIPTION
  Orchestrates per-service backups within a time window, mandatory services
  first, recording events and reporting the result. Services are described in a
  JSON config and implemented by step scripts (recipes or bespoke). See docs/ for
  internals and help/ for usage.
.PARAMETER Command
  plan | run | history | help
.PARAMETER ConfigPath
  Path to config.json. Defaults to the OS config dir (see help/).
.PARAMETER Force
  Bypass the time-window gate (manual/test runs).
.PARAMETER Limit
  history: number of recent runs to show.
.EXAMPLE
  pwsh sequencer.ps1 plan
.EXAMPLE
  pwsh sequencer.ps1 run -ConfigPath ./config.json -Force
#>

[CmdletBinding()]
param(
    [Parameter(Position = 0)][string]$Command = 'help',
    [string]$ConfigPath,
    [switch]$Force,
    [int]$Limit = 20,
    [switch]$Help
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

$BaseDir = $PSScriptRoot
Import-Module (Join-Path $BaseDir 'lib/BackupCommon.psm1') -Force

function Get-ConfigDir {
    if ($env:BACKUP_SEQUENCER_CONFIG_DIR) { return $env:BACKUP_SEQUENCER_CONFIG_DIR }
    if ($IsWindows) { return (Join-Path $env:ProgramData 'backup-sequencer') }
    return '/etc/backup-sequencer'
}

function Get-VarDir {
    if ($env:BACKUP_SEQUENCER_VAR_DIR) { return $env:BACKUP_SEQUENCER_VAR_DIR }
    if ($IsWindows) { return (Join-Path (Join-Path $env:ProgramData 'backup-sequencer') 'var') }
    return '/var/lib/backup-sequencer'
}

function Show-Usage {
    @'
backup sequencer

Usage:
  pwsh sequencer.ps1 <command> [-ConfigPath <path>] [-Force] [-Limit <n>]

Commands:
  plan      Show the ordered plan for the current window (no side effects)
  run       Execute the plan
  history   Show recent run summaries (newest first)
  help      This message

Config resolution (unless -ConfigPath is given):
  Linux:    /etc/backup-sequencer/config.json
  Windows:  %ProgramData%\backup-sequencer\config.json
'@ | Write-Host
}

if ($Help -or $Command -eq 'help') {
    Show-Usage
    return
}

if (-not $ConfigPath) {
    $ConfigPath = Join-Path (Get-ConfigDir) 'config.json'
}
if (-not (Test-Path -LiteralPath $ConfigPath)) {
    Write-Error "Config not found: $ConfigPath"
    return
}
$Config = Get-Content -LiteralPath $ConfigPath -Raw | ConvertFrom-Json

$VarDir = Get-VarDir
$StagingRoot = Join-Path $VarDir 'staging'
if ((Test-HasProp $Config 'staging') -and $Config.staging) {
    $StagingRoot = $Config.staging
}
$Paths = @{
    BaseDir     = $BaseDir
    EventsPath  = Join-Path $VarDir 'events.jsonl'
    LockPath    = Join-Path $VarDir 'sequencer.lock'
    StagingRoot = $StagingRoot
}

switch ($Command) {
    'plan' {
        $proj = Get-ServiceProjection -EventsPath $Paths.EventsPath
        $plan = Get-BackupPlan -Config $Config -Projection $proj
        Write-Host ("Plan  window={0}-{1}  (within window now: {2})" -f `
                $Config.window.open, $Config.window.close, (Test-WithinWindow $Config.window.open $Config.window.close))
        foreach ($p in $plan) {
            $flag = if ($p.Mandatory) { '*' } else { ' ' }
            $last = if ($p.LastSuccess) { $p.LastSuccess } else { 'never' }
            Write-Host ("  {0} {1,-24} est={2,6:N0}s  lastSuccess={3}" -f $flag, $p.Service, $p.EstimatedSec, $last)
        }
    }
    'run' {
        $runId = Invoke-BackupRun -Config $Config -Paths $Paths -Force:$Force
        if ($runId) {
            $report = Format-RunReport -EventsPath $Paths.EventsPath -RunId $runId
            Write-Host $report
            if ((Test-HasProp $Config 'notify') -and $Config.notify.enabled) {
                Send-BackupReport -Notify $Config.notify -Subject "backup report $runId" `
                    -Body $report -BaseDir (Get-ConfigDir) | Out-Null
            }
        }
    }
    'history' {
        $events = Get-BackupEvents -EventsPath $Paths.EventsPath
        $runEnds = @($events | Where-Object { $_.type -eq 'run.end' })
        $recent = @($runEnds | Select-Object -Last $Limit)
        [array]::Reverse($recent)
        foreach ($r in $recent) {
            Write-Host ("{0}  ok={1} failed={2} planned={3}" -f $r.ts, $r.summary.ok, $r.summary.failed, $r.summary.planned)
        }
    }
    default {
        Write-Host "Unknown command: $Command"
        Show-Usage
    }
}
